  { name = "free-fly", source = "shared/free-fly", version = "1.8.4", options = {["altitude"]={label="FLY ALTITUDE",help="How high you fly; MED clears rooftops in voxel view."},["motion"]={label="FLY MOTION",help="Animate the ride instead of sliding."},["size"]={label="FLY SIZE"}} },
  { name = "wild-skies", source = "shared/wild-skies", version = "1.12.3", options = {["motion"]={label="BIRD MOTION"}} },
